import { useEffect, useState, useCallback } from 'react';
import api, { getError } from '../lib/api';
import { getUser } from '../lib/auth';
import { Spinner, Empty, Toast } from '../components/UI';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { 
  faMagnifyingGlass, 
  faCalendarCheck, 
  faCircle, 
  faHandshakeAngle,
  faCode,         
  faServer,       
  faCubes,        
  faTerminal,     
  faLayerGroup,   
  faDatabase,     
  faBoxOpen,      
  faCodeBranch    
} from '@fortawesome/free-solid-svg-icons';

const RECOGNIZED_SKILLS = [
  { name: 'React.js', icon: faCode },
  { name: 'Node.js', icon: faServer },
  { name: 'Java', icon: faCubes },
  { name: 'JavaScript', icon: faTerminal },
  { name: 'TypeScript', icon: faTerminal },
  { name: 'Python', icon: faTerminal },
  { name: 'Next.js', icon: faLayerGroup },
  { name: 'Express.js', icon: faServer },
  { name: 'SQL', icon: faDatabase },
  { name: 'MongoDB', icon: faDatabase },
  { name: 'Docker', icon: faBoxOpen },
  { name: 'Git', icon: faCodeBranch }
];

export default function SearchMentor() {
  const user = getUser();
  const isMentorAccount = user?.role === 'mentor';

  const [selectedSkill, setSelectedSkill] = useState('React.js');
  const [mentorsList, setMentorsList] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [activeBookingId, setActiveBookingId] = useState('');
  const [toastMessage, setToastMessage] = useState('');

  const handleSearchMentors = useCallback(async () => {
    setIsLoading(true);
    setToastMessage('');
    try {
      const { data } = await api.get('/user/mentors', { params: { skills: selectedSkill } });
      setMentorsList(Array.isArray(data) ? data : []);
    } catch (error) {
      setToastMessage(getError(error));
    } finally {
      setIsLoading(false);
    }
  }, [selectedSkill]);

  useEffect(() => {
    handleSearchMentors();
  }, [handleSearchMentors]);

  const handleBookSession = async (mentor) => {
    setActiveBookingId(mentor._id);
    try {
      await api.post('/appointments/request', { mentorId: mentor._id, skill: selectedSkill });
      setToastMessage(`Request sent to ${mentor.name}.`);
    } catch (error) {
      setToastMessage(getError(error));
    } finally {
      setActiveBookingId('');
    }
  };

  const isSuccessNotification = toastMessage.startsWith('Request');

  return (
    <div className="space-y-8">
      <header>
        <span className="text-xs font-bold tracking-wider text-indigo-600 uppercase block mb-1">
          MENTOR DIRECTORY
        </span>
        <h1 className="text-3xl font-extrabold tracking-tight text-slate-900">Find a mentor</h1>
        <p className="text-slate-500 mt-1 text-sm leading-relaxed">
          Choose a skill and discover mentors ready to help.
        </p>
      </header>

      <nav aria-label="Skills Filter" className="border-b border-slate-200 pb-3">
        <div className="flex gap-2 overflow-x-auto pb-1" role="tablist">
          {RECOGNIZED_SKILLS.map((skillItem) => {
            const isTabActive = selectedSkill === skillItem.name;
            return (
              <button 
                key={skillItem.name} 
                role="tab" 
                aria-selected={isTabActive}
                onClick={() => setSelectedSkill(skillItem.name)}
                className={`px-4 py-2 rounded-full text-xs font-medium whitespace-nowrap transition-colors flex items-center gap-2 cursor-pointer ${
                  isTabActive 
                    ? 'bg-indigo-600 text-white shadow-sm shadow-indigo-100' 
                    : 'text-slate-500 hover:bg-slate-100 hover:text-slate-900'
                }`}
              >
                <FontAwesomeIcon icon={skillItem.icon} className="text-sm" />
                <span>{skillItem.name}</span>
              </button>
            );
          })}
        </div>
      </nav>

      <main className="w-full">
        {isLoading ? (
          <div className="flex items-center gap-3 justify-center text-slate-500 py-16 bg-white border border-slate-200 rounded-2xl shadow-xs">
            <Spinner /> 
            <span className="text-sm font-medium">Searching mentors…</span>
          </div>
        ) : mentorsList.length ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
            {mentorsList.map((mentorItem) => {
              const isCurrentlyBookingThis = activeBookingId === mentorItem._id;
              
              let actionButtonContent;
              if (isCurrentlyBookingThis) {
                actionButtonContent = <Spinner />;
              } else if (isMentorAccount) {
                actionButtonContent = <span>Learners only</span>;
              } else {
                actionButtonContent = (
                  <div className="flex items-center gap-2">
                    <FontAwesomeIcon icon={faCalendarCheck} />
                    <span>Request session</span>
                  </div>
                );
              }

              return (
                <article 
                  key={mentorItem._id} 
                  className="bg-white border border-slate-200 rounded-xl p-5 shadow-xs flex flex-col justify-between gap-4 transition-all hover:border-slate-300"
                >
                  <div className="flex gap-3 items-start">
                    <div 
                      className="w-11 h-11 bg-slate-100 border border-slate-200 rounded-full flex items-center justify-center flex-shrink-0 overflow-hidden select-none"
                      aria-hidden="true"
                    >
                      <img 
                        src='data:image/jpeg;base64,' 
                        alt="Avatar" 
                        className="w-full h-full object-cover"
                      />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex justify-between items-start gap-2">
                        <div className="truncate">
                          <h3 className="text-sm font-bold text-slate-900 truncate leading-tight">
                            {mentorItem.name}
                          </h3>
                          <span className="text-[10px] text-slate-400 font-semibold tracking-wide">
                            Mentor
                          </span>
                        </div>
                        <span className="text-[10px] font-bold text-emerald-600 bg-emerald-50 border border-emerald-100/60 px-1.5 py-0.5 rounded flex items-center gap-1 whitespace-nowrap select-none">
                          <FontAwesomeIcon icon={faCircle} className="text-[6px]" /> Available
                        </span>
                      </div>
                      <p className="text-xs text-slate-400 mt-2 truncate select-all">
                        {mentorItem.email}
                      </p>
                    </div>
                  </div>

                  <div className="flex flex-wrap gap-1.5 mt-1">
                    {(mentorItem.skills || []).map((skillTag) => (
                      <span 
                        key={skillTag} 
                        className="text-[10px] font-medium bg-slate-50 text-slate-500 border border-slate-200 px-2 py-0.5 rounded"
                      >
                        {skillTag}
                      </span>
                    ))}
                  </div>

                  <button 
                    disabled={!!activeBookingId || isMentorAccount} 
                    onClick={() => handleBookSession(mentorItem)}
                    className={`w-full py-2.5 rounded-xl text-xs font-semibold shadow-2xs transition-colors flex items-center justify-center gap-1.5 select-none ${
                      isMentorAccount
                        ? 'bg-slate-100 text-slate-400 border border-slate-200 cursor-not-allowed'
                        : 'bg-indigo-600 hover:bg-indigo-700 text-white cursor-pointer'
                    }`}
                  >
                    {actionButtonContent}
                  </button>
                </article>
              );
            })}
          </div>
        ) : (
          <Empty 
            icon={<FontAwesomeIcon icon={faHandshakeAngle} className="text-3xl text-indigo-500" />} 
            title="No mentors found" 
            text={`We couldn't find any mentors available for ${selectedSkill} right now.`} 
          />
        )}
      </main>

      {toastMessage && (
        <Toast 
          message={toastMessage} 
          type={isSuccessNotification ? 'success' : 'error'} 
          onClose={() => setToastMessage('')} 
        />
      )}
    </div>
  );
}
